mapper.select:
SELECT e.category_revision,s.active_revision,s.active_mapping_id,s.active_mapping_version
FROM expense_configuration e LEFT JOIN account_mapping_scope s
ON s.tenant_id=e.tenant_id AND s.legal_entity_id=#{entity} AND s.currency=#{currency} WHERE e.tenant_id=#{tenant}

SELECT a.*,d.mapping_key FROM account_mapping_activation a JOIN account_mapping_draft d
ON d.tenant_id=a.tenant_id AND d.id=a.mapping_id
WHERE a.tenant_id=#{tenant} AND a.legal_entity_id=#{entity} AND a.currency=#{currency} AND a.revision<#{before} ORDER BY a.revision DESC LIMIT #{limit}


SELECT id,mapping_key,name,legal_entity_id,currency,revision,published_version,published_draft_revision,updated_by,updated_at
FROM account_mapping_draft WHERE tenant_id=#{argument1} AND mapping_key>#{argument2}
 AND legal_entity_id=#{argument3} AND currency=#{argument4} ORDER BY mapping_key LIMIT #{argument5}
